import"./chunk-2NFLSA4Y.js";var t={atomicSpectra:{param:{levelA:"First selected level n\u2081",levelB:"Second selected level n\u2082",mode:"Photon exchange",timeStep:"Animation time step"},hint:{level:"Choose two integer levels from 1 to 6. Emission goes from the higher-energy level to the lower one; absorption reverses it. The control order does not matter.",mode:"Absorption needs a photon with exactly the selected energy gap. This model supplies that matching photon."},measure:{wavelength:"Photon wavelength (vacuum)",transitionEnergy:"Energy exchanged in the transition",currentLevel:"Occupied level",time:"Animation time",frequency:"Photon frequency",electronEnergy:"Electron bound-state energy",photonEnergy:"Energy in the photon",totalEnergy:"Electron + photon energy",ionisationEnergy:"Energy needed to ionise from this level",energyError:"Energy balance error"},graph:{energy:"Discrete transition and energy conservation"},view:{electronSign:"\u2212",diagram:"Hydrogen \xB7 schematic level spacing",emission:"Emission: electron drops, photon leaves",absorption:"Absorption: photon enters, electron rises",same:"Same level: no transition",noPhoton:"No photon \xB7 wavelength is not defined",spectrum:"Visible wavelength guide \xB7 approximate colours",visible:"visible light",uv:"ultraviolet",ir:"infrared",photonOption:"Animated photon",transitionOption:"Transition arrow"},theory:{concept:"[[An atomic spectrum is the set of wavelengths of light that the atoms of an element emit or absorb; each element has its own spectrum, like a fingerprint.]] The spectrum is made of separate lines because an electron in an atom can have only certain allowed energies \u2014 energy levels. When the electron moves from a higher level to a lower one, the atom emits one photon whose energy equals the difference between the levels: E\u03B3 = |Ef \u2212 Ei| = h\xB7\u03BD. Absorbing a photon of exactly that energy lifts the electron back up. For hydrogen the levels are E\u2099 \u2248 \u221213.6 eV / n\xB2."},section:{levels:{title:"Allowed energies",text:"The ground state n = 1 is the most tightly bound. Higher n means energy closer to zero, not a classical orbit drawn here. Zero energy represents a free electron far from the proton. Energy levels crowd together as n increases; the drawing spreads them for readability."},photon:{title:"One energy gap, one photon",text:"[[In emission the electron loses energy and the photon carries exactly that amount away.]] A larger gap produces a higher frequency and a shorter wavelength. The electron changes its energy discretely; the arrow does not mean it can occupy intermediate energies."},series:{title:"Spectral series",text:"Transitions ending at n = 1 form the ultraviolet Lyman series. Those ending at n = 2 form the Balmer series, including 3 \u2192 2 near 656.47 nm and 4 \u2192 2 near 486.27 nm in vacuum. Transitions ending at n = 3 form the infrared Paschen series. Only the chosen line is shown, not a full gas spectrum."},absorption:{title:"Reversing the exchange",text:"[[A matching incoming photon transfers its energy to the electron, raising it to the higher level.]] The same pair of levels uses the same wavelength in absorption and emission. In a continuous spectrum absorption removes that wavelength; the dark marker illustrates this missing line."}},formula:{difference:"Photon energy is the level difference",levels:"Hydrogen bound-state energies",photon:"Photon energy, frequency and wavelength",rydberg:"Rydberg relation: R_H = 10 967 758.340 m\u207B\xB9"},variable:{n:"Principal quantum number (integer)",energy:"Electron energy and photon energy",wavelength:"Vacuum wavelength",frequency:"Photon frequency",h:"Planck constant: 6.62607015 \xD7 10\u207B\xB3\u2074 J\xB7s",c:"Speed of light: 299 792 458 m/s"},assumption:{hydrogen:"One hydrogen atom, one electron and levels n = 1\u20266. The nonrelativistic Coulomb formula includes the electron-proton reduced mass. It does not model many-electron atoms.",quantum:"Fine and hyperfine structure, selection rules, polarisation, recoil, line widths and cascades are omitted. The selected pair represents a compatible transition; no transition probabilities or lifetimes are predicted.",time:"The exchange occurs after 1 animation second and the run ends after 3 seconds. Photon movement is a slowed schematic cue, not real light speed or an atomic lifetime. The graph time is animation time.",diagram:"The energy diagram is not to scale: levels have equal visual spacing to keep labels readable. Their numeric energies are physical. The dot is a state marker, not an electron trajectory.",spectrum:"Wavelengths are in vacuum; measurements in air differ slightly. The coloured 380\u2013780 nm strip is only a guide with approximate colours. UV and IR photons are outside it. Line brightness is illustrative, not a predicted intensity.",equal:"Equal selected levels exchange no photon. In that case the wavelength reading is 0 as a no-photon indicator, not a physical zero-wavelength photon. Fractional n inputs are rounded to the nearest integer."},challenge:{red:{title:"Find the red line",description:"Complete a photon exchange near 656 nm.",hint:"Try levels 3 and 2."},blue:{title:"Find the blue-green line",description:"Complete a photon exchange near 486 nm.",hint:"Try levels 4 and 2."},uv:{title:"Go beyond visible light",description:"Exchange a photon shorter than 380 nm.",hint:"Use the ground state as one of the levels."},absorb:{title:"Raise the electron",description:"Absorb a photon and finish on a higher-energy level.",hint:"Switch to absorption and choose distinct levels."},ir:{title:"Find an infrared transition",description:"Exchange a photon longer than 780 nm.",hint:"Try levels 4 and 3."},balance:{title:"Account for every electronvolt",description:"Exchange more than 10 eV with an energy balance error below 10\u207B\xB9\u2070 eV.",hint:"Try levels 2 and 1 and inspect the total energy graph."}},preset:{n1:"n = 1",n2:"n = 2",n3:"n = 3",n4:"n = 4",n6:"n = 6"}}},o={sim:t};export{o as default,t as sim};
